def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0}
    up = down = 0
    while cells:
        start = cells.pop()
        comp = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if q in cells:
                    cells.remove(q)
                    comp.add(q)
                    stack.append(q)
        if len(comp) != 4:
            continue
        rmin = min(r for r, c in comp)
        rmax = max(r for r, c in comp)
        cmin = min(c for r, c in comp)
        cmax = max(c for r, c in comp)
        normalized = {(r-rmin, c-cmin) for r, c in comp}
        if normalized == {(0,1),(1,0),(1,1),(1,2)}:
            up += 1
        elif normalized == {(0,0),(0,1),(0,2),(1,1)}:
            down += 1
    out = [[0] * 6 for _ in range(3)]
    slots = ((0,0),(2,0),(0,2),(2,2))
    for n, color, offset in ((up,3,0),(down,1,3)):
        for r, c in slots[:min(n,4)]:
            out[r][offset+c] = color
    return out
